package com.desktodo.app;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import android.content.pm.PackageManager;import org.json.*;import java.time.Instant;import java.util.*;
final class ReminderScheduler {
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("mojian-reminders",0);}
 static JSONObject settings(Context c){android.content.SharedPreferences p=prefs(c);JSONObject j=new JSONObject();try{j.put("enabled",p.getBoolean("enabled",false)).put("quietEnabled",p.getBoolean("quietEnabled",true)).put("quietStart",p.getInt("quietStart",22)).put("quietEnd",p.getInt("quietEnd",8));}catch(Exception ignored){}return j;}
 static void configure(Context c,JSONObject j)throws Exception {android.content.SharedPreferences.Editor e=prefs(c).edit();for(String k:new String[]{"enabled","quietEnabled"})if(j.has(k)){AgentTools.booleanValue(j,k);e.putBoolean(k,j.getBoolean(k));}for(String k:new String[]{"quietStart","quietEnd"})if(j.has(k))e.putInt(k,AgentTools.integer(j,k,0,23));if(!e.commit())throw new Exception("提醒设置保存失败");reconcile(c,true);}
 static boolean permitted(Context c){return (Build.VERSION.SDK_INT<33||c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==PackageManager.PERMISSION_GRANTED)&&c.getSystemService(NotificationManager.class).areNotificationsEnabled();}
 static PendingIntent pending(Context c,String key){Intent i=new Intent(c,ReminderReceiver.class).setAction("com.desktodo.app.REMIND").setData(Uri.parse("mojian://reminder/"+Uri.encode(key))).putExtra("key",key);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static JSONArray tasks(Context c)throws Exception{return new JSONArray(c.getSharedPreferences("mojian-native",0).getString("tasks","[]"));}
 static synchronized void reconcile(Context c,boolean force){try{JSONObject s=settings(c);JSONArray tasks=tasks(c);String signature=tasks.toString()+s.toString()+permitted(c);android.content.SharedPreferences p=prefs(c);if(!force&&signature.equals(p.getString("signature","")))return;AlarmManager am=c.getSystemService(AlarmManager.class);for(String key:p.getStringSet("scheduled",Collections.emptySet()))am.cancel(pending(c,key));Set<String> keys=new HashSet<>();JSONObject records=new JSONObject();if(permitted(c)){Set<String> sent=new HashSet<>();for(java.util.Map.Entry<String,?> item:p.getAll().entrySet())if(item.getKey().startsWith("sent.")&&Boolean.TRUE.equals(item.getValue()))sent.add(item.getKey().substring(5));records=ReminderPlan.build(tasks,s,System.currentTimeMillis(),sent);for(Iterator<String> it=records.keys();it.hasNext();){String key=it.next();long at=records.getJSONObject(key).getLong("at");PendingIntent pi=pending(c,key);if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);keys.add(key);}}
 p.edit().putStringSet("scheduled",keys).putString("records",records.toString()).putString("signature",signature).apply();}catch(Exception ignored){prefs(c).edit().remove("signature").apply();}}
 static synchronized void fire(Context c,String key){try{android.content.SharedPreferences p=prefs(c);if(key==null||p.getBoolean("sent."+key,false)||!settings(c).optBoolean("enabled")||!permitted(c))return;JSONObject r=new JSONObject(p.getString("records","{}")).optJSONObject(key);if(r==null)return;JSONObject task=null;JSONArray a=tasks(c);for(int n=0;n<a.length();n++){JSONObject t=a.getJSONObject(n);if(t.optString("id").equals(r.getString("id"))&&!t.isNull("due")&&Instant.parse(t.getString("due")).toEpochMilli()==r.getLong("due"))task=t;}if(task==null)return;JSONObject s=settings(c);long now=System.currentTimeMillis(),next=ReminderPolicy.next(r.getLong("due"),now,r.getBoolean("before"),s.optBoolean("quietEnabled"),s.optInt("quietStart"),s.optInt("quietEnd"));if(next<0)return;if(next>now+5000){reconcile(c,true);return;}
 NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("todo-due","待办到期提醒",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(c,MainActivity.class);PendingIntent content=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notification=new Notification.Builder(c,"todo-due").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(r.getBoolean("before")?"待办将在10分钟内到期":"待办已到期").setContentText(task.getString("title")).setStyle(new Notification.BigTextStyle().bigText(task.getString("title"))).setContentIntent(content).setAutoCancel(true).build();nm.notify(key,1,notification);p.edit().putBoolean("sent."+key,true).commit();reconcile(c,true);
 }catch(Exception ignored){}}
}
